ROS_ROOT = Path(__file__).resolve().parents[1] WORKSPACE = ROS_ROOT.parents[1] LEARNER = (WORKSPACE / "ns-allinone-3.40/ns-3.40/contrib/opengym/examples/" "wireless-rl/mr3_learning") SHUTDOWN_PROTOCOL = "nav2-finalized_then_serial-ros_then_gazebo-v1" NAV2_NODES = ("controller_server", "planner_server", "behavior_server", "bt_navigator", "waypoint_follower", "velocity_smoother") NAV2_SHUTDOWN_WALL_GUARD_SEC = 30. MOTION_OUTPUT_PUBLISHER = ("/", "motion_safety") MOTION_PHASE_COMPLETION = "publication_and_local_topic_receipt" PLANT_QUANTUM_NS = 20_000_000 STARTUP_READINESS_PROTOCOL = "received-input-pause-drain-v1" STARTUP_CLEANUP_RESERVE_SEC = 60. STARTUP_RESPONSE_RESERVE_SEC = 5.
def plant_stimulus_angular(arm, relative_ns): """Fixed from-rest engineering waveform; no state/truth-dependent trigger.""" if arm not in ("continuous", "pulse") or type(relative_ns) is not int or relative_ns < 0: raise ValueError("invalid fixed plant stimulus coordinate") turning = 1_200_000_000 <= relative_ns < 2_740_000_000 pulse = arm == "pulse" and 2_200_000_000 <= relative_ns < 2_240_000_000 return 800 if turning and not pulse else 0 spec = importlib.util.spec_from_file_location("mr3_pipe_protocol", LEARNER / "ipc.py") ipc = importlib.util.module_from_spec(spec) spec.loader.exec_module(ipc)
def motion_authority_profile_from_request(request): """Receiving permission is fixed by the new Reach contract, not a CLI knob.""" if type(request) is not dict: raise ValueError("worker reset request is not an object") contract = request.get("safety_contract", "legacy") if type(contract) is not str or contract not in ("legacy", "mr3-reach-v1"): raise ValueError("unknown safety contract for receiving authority") expected = MOTION_AUTHORITY_PROFILE if contract == "mr3-reach-v1" else None selected = request.get("motion_authority_profile") if ((expected is None and selected is not None) or (expected is not None and (type(selected) is not str or selected != expected))): raise ValueError("worker receiving-authority profile differs from fixed reset contract") return expected
class Worker: """Coordinate real physical steps, delivered observations and isolated reward."""
